update public.i365_item_types t set fields = s.j->'exp_fields'
from _i365_legacy s
where t.slug = 'experience' and not (t.fields @> '[{"key":"period_th"}]'::jsonb);

insert into public.i365_site_settings (key, value)
select e.key, e.value from _i365_legacy s cross join lateral jsonb_each(s.j->'settings') e
on conflict (key) do nothing;

insert into public.i365_items (section_id, item_type_id, title_th, title_en, summary_th, cover_image, data, is_published, sort_order)
select sec.id, sec.item_type_id, it->>'title_th', it->>'title_en', it->>'summary_th', it->>'cover_image', it->'data',
  coalesce((it->>'is_published')::boolean, true), o
from _i365_legacy s cross join lateral jsonb_array_elements(s.j->'items') with ordinality x(it, o)
join public.i365_islands isl on isl.slug = it->>'island'
join public.i365_sections sec on sec.island_id = isl.id and sec.slug = it->>'section'
where not exists (select 1 from public.i365_items z where z.section_id = sec.id and z.title_th = it->>'title_th');

drop table if exists _i365_legacy;
